  const incomingRefs = [{"id":"ref-018","term":"Short-range order (SRO)","definition":"Local atomic or ionic order over short distances.","detail":"A solid with only SRO is described as amorphous in Week 3.","tags":["week 3","order","structure"]},{"id":"ref-019","term":"Lattice","definition":"Periodic array of equivalent points used to describe crystal repetition.","detail":"The lecture separates lattice from the basis attached to each point.","tags":["week 3","crystal"]},{"id":"ref-020","term":"Basis","definition":"Atom or group of atoms associated with each lattice point.","detail":"Lattice plus basis defines the crystal structure.","tags":["week 3","crystal"]},{"id":"ref-021","term":"Unit cell","definition":"Repeat unit representing the periodicity and symmetry of a crystal.","detail":"Classified with axial lengths and interaxial angles.","tags":["week 3","crystal"]},{"id":"ref-022","term":"Coordination number","definition":"Number of nearest neighbors touching a given atom.","detail":"SC 6, BCC 8, FCC 12, HCP 12.","tags":["week 3","unit cell"]},{"id":"ref-023","term":"Atomic packing factor (APF)","definition":"Fraction of unit-cell volume occupied by hard-sphere atoms.","detail":"SC 0.52, BCC 0.68, FCC/HCP 0.74.","tags":["week 3","unit cell","formula"]},{"id":"ref-024","term":"SC radius–lattice relation","definition":"a₀ = 2r.","detail":"Atoms touch along an edge.","tags":["week 3","SC","formula"]},{"id":"ref-025","term":"BCC radius–lattice relation","definition":"a₀ = 4r/√3.","detail":"Atoms touch along the body diagonal.","tags":["week 3","BCC","formula"]},{"id":"ref-026","term":"FCC radius–lattice relation","definition":"a₀ = 4r/√2.","detail":"Atoms touch along a face diagonal.","tags":["week 3","FCC","formula"]},{"id":"ref-027","term":"Theoretical density","definition":"ρ=(atoms/cell×atomic mass)/(unit-cell volume×Avogadro number).","detail":"Example 3-5 gives 7.879 g/cm³ for BCC iron.","tags":["week 3","density","formula"]},{"id":"ref-028","term":"Miller direction indices","definition":"[uvw] from head−tail coordinates with fractions cleared.","detail":"Coordinates are referenced to a right-handed system; negative indices use overbars, and symmetry-equivalent direction families use ⟨uvw⟩.","tags":["week 3","Miller","direction"]},{"id":"ref-029","term":"Miller plane indices","definition":"(hkl) from reciprocals of axis intercepts.","detail":"Move the origin if needed; equivalent families use {hkl}.","tags":["week 3","Miller","plane"]},{"id":"ref-030","term":"Repeat distance","definition":"Distance between equivalent lattice points along a direction.","detail":"Linear density is the reciprocal.","tags":["week 3","direction"]},{"id":"ref-031","term":"Interplanar distance (cubic)","definition":"dₕₖₗ=a₀/√(h²+k²+l²).","detail":"Spacing between adjacent parallel planes.","tags":["week 3","plane","formula"]},{"id":"ref-032","term":"Anisotropic","definition":"Properties vary with direction.","detail":"Contrasted with isotropic behavior.","tags":["week 3","property"]},{"id":"ref-033","term":"Interstitial site","definition":"Geometric site between lattice atoms where a smaller atom may fit.","detail":"Cubic, tetrahedral, and octahedral sites are shown.","tags":["week 3","crystal"]},{"id":"ref-034","term":"Bragg relation","definition":"sinθ=λ/(2dₕₖₗ), equivalently λ=2dₕₖₗsinθ.","detail":"Basis of the XRD discussion.","tags":["week 3","XRD","formula"]},{"id":"ref-035","term":"X-ray diffraction (XRD)","definition":"Identifies crystallographic planes in a powdered sample so crystal structure can be inferred.","detail":"The lecture notes roughly 30–60 min collection.","tags":["week 3","diffraction"]},{"id":"ref-036","term":"Transmission electron microscopy (TEM)","definition":"High-energy-electron technique for fine-scale microstructure imaging.","detail":"High resolution but demanding preparation/analysis and expensive equipment.","tags":["week 3","microscopy"]},{"id":"ref-037","term":"Point defect","definition":"Localized disruption in a regular atomic or ionic arrangement.","detail":"Includes vacancy, interstitial, and substitutional defects.","tags":["week 4","defect"]},{"id":"ref-038","term":"Vacancy","definition":"Missing atom or ion at its normal site.","detail":"nᵥ=n exp(−Qᵥ/RT).","tags":["week 4","point defect","formula"]},{"id":"ref-039","term":"Interstitial defect","definition":"Extra atom or ion at a normally unoccupied site.","detail":"Local distortion can strengthen the material.","tags":["week 4","point defect"]},{"id":"ref-040","term":"Substitutional defect","definition":"A different atom or ion replaces a normal lattice atom.","detail":"Size mismatch distorts the lattice.","tags":["week 4","point defect"]},{"id":"ref-041","term":"Dislocation","definition":"Line imperfection in a crystal.","detail":"Screw, edge, and mixed dislocations are listed.","tags":["week 4","dislocation"]},{"id":"ref-042","term":"Slip plane","definition":"Plane containing the dislocation line and Burgers vector.","detail":"Dislocations move by slip under sufficient shear.","tags":["week 4","slip"]},{"id":"ref-043","term":"Slip system","definition":"Combination of a slip plane and slip direction.","detail":"Preferred systems use dense directions and planes.","tags":["week 4","slip"]},{"id":"ref-044","term":"Plastic deformation","definition":"Irreversible shape change remaining after the load is removed.","detail":"Cumulative dislocation slip is a major mechanism.","tags":["week 4","deformation"]},{"id":"ref-045","term":"Schmid's law","definition":"τᵣ=σcosφcosλ.","detail":"Resolves applied normal stress onto a slip system.","tags":["week 4","slip","formula"]},{"id":"ref-046","term":"Critical resolved shear stress (CRSS)","definition":"Resolved shear-stress threshold required for slip.","detail":"Slip starts when τᵣ reaches τCRSS.","tags":["week 4","slip"]},{"id":"ref-047","term":"Cross-slip","definition":"A moving dislocation switches from one slip system to another.","detail":"Occurs after an obstacle redirects motion.","tags":["week 4","slip"]},{"id":"ref-048","term":"Grain boundary","definition":"Narrow zone separating differently oriented crystals.","detail":"Boundaries obstruct dislocation motion.","tags":["week 4","surface defect"]},{"id":"ref-049","term":"Hall–Petch equation","definition":"σᵧ=σ₀+Kd⁻¹ᐟ².","detail":"Relates grain size to yield strength.","tags":["week 4","grain","formula"]},{"id":"ref-050","term":"Small-angle grain boundary","definition":"Array of dislocations producing a small misorientation.","detail":"A surface/planar defect.","tags":["week 4","surface defect"]},{"id":"ref-051","term":"Stacking fault","definition":"Error in the stacking of close-packed planes.","detail":"The lecture mentions these in FCC metals.","tags":["week 4","surface defect"]},{"id":"ref-052","term":"Twin boundary","definition":"Plane across which the crystal has mirror-image misorientation.","detail":"A planar defect.","tags":["week 4","surface defect"]},{"id":"ref-053","term":"Strain hardening","definition":"Strengthening by deformation that increases dislocation density.","detail":"More dislocations create more obstacles.","tags":["week 4","strengthening"]},{"id":"ref-054","term":"Solid-solution strengthening","definition":"Strengthening by interstitial or substitutional guest atoms.","detail":"Guest atoms obstruct dislocation motion.","tags":["week 4","strengthening"]},{"id":"ref-055","term":"Grain-size strengthening","definition":"Strengthening by reducing average grain size.","detail":"More boundaries impede dislocations.","tags":["week 4","strengthening"]},{"id":"ref-056","term":"Annealing after strain hardening","definition":"Heat treatment that decreases dislocation density and increases ductility.","detail":"Presented as reversing strain-hardening effects.","tags":["week 4","annealing"]},{"id":"ref-057","term":"Peierls–Nabarro stress","definition":"Stress required to move a dislocation between equivalent equilibrium positions.","detail":"Lecture form: τ = c exp(−kd/b).","tags":["week 4","dislocation","formula"]},{"id":"ref-058","term":"CsCl lattice and basis","definition":"The lecture example treats CsCl as a simple-cubic lattice with a two-ion basis, not a BCC lattice.","detail":"Cl⁻ at corners and Cs⁺ at (1/2,1/2,1/2) are not equivalent lattice points; the cell contains two ions.","tags":["week 3","crystal","example"]},{"id":"ref-059","term":"Planar density","definition":"Number of atom centers lying on a crystallographic plane divided by that plane's area.","detail":"Example 3-9 gives 8.96 atoms/nm² for the SC (010) plane with a₀=0.334 nm, while the parallel (020) plane has zero in that example.","tags":["week 3","plane","density"]},{"id":"ref-060","term":"Interstitial radius-ratio ranges","definition":"Source table: CN2 0–0.155; CN3 0.155–0.225; CN4 0.225–0.414; CN6 0.414–0.732; CN8 0.732–1.000.","detail":"The relative atom size selects linear, triangular, tetrahedral, octahedral, or cubic coordination environments.","tags":["week 3","interstitial","table"]},{"id":"ref-061","term":"Characteristic FCC slip system","definition":"{111} slip planes with ⟨110⟩ slip directions.","detail":"Listed in the Week 4 source Table 4-1.","tags":["week 4","slip","FCC"]},{"id":"ref-062","term":"Characteristic BCC slip systems","definition":"{110}, {112}, and {123} slip-plane families with ⟨111⟩ directions.","detail":"Listed in the Week 4 source Table 4-1.","tags":["week 4","slip","BCC"]},{"id":"ref-063","term":"Dislocation pile-up","definition":"Accumulation of moving dislocations at an obstacle.","detail":"The Week 4 lecture labels a pile-up-at-an-obstacle figure as work hardening.","tags":["week 4","dislocation","strengthening"]},{"id":"ref-064","term":"Frenkel defect","definition":"Vacancy–interstitial pair formed when an ion leaves its normal lattice site and occupies an interstitial site.","detail":"Shown in the Week 4 point-defect source figure.","tags":["week 4","point defect","ionic"]},{"id":"ref-065","term":"Schottky defect","definition":"Charge-balanced combination of cation and anion vacancies in an ionic crystal.","detail":"Shown in the Week 4 point-defect source figure and constrained by the lecture's charge-balance rule.","tags":["week 4","point defect","ionic"]},{"id":"ref-066","term":"Seven crystal systems","definition":"Cubic, tetragonal, orthorhombic, hexagonal, rhombohedral/trigonal, monoclinic, and triclinic.","detail":"Classified by relationships among axial lengths and interaxial angles.","tags":["week 3","crystal","classification"]},{"id":"ref-067","term":"Source CRSS comparison","definition":"Table 4-2 lists FCC 345–690 kPa, BCC 34,500–69,000 kPa, and HCP (c/a≥1.633) 345–690 kPa for basal slip.","detail":"The comparison is explicitly for nearly perfect crystals; engineering materials are usually polycrystalline.","tags":["week 4","CRSS","table"]},{"id":"ref-068","term":"Surface-imperfection energy","definition":"Energetic cost per unit area associated with planar defects such as stacking faults, twin boundaries, and grain boundaries.","detail":"Source Table 4-3 gives material-specific values for Al, Cu, Pt, and Fe.","tags":["week 4","surface defect","table"]},{"id":"ref-069","term":"Burgers vector","definition":"Vector that quantifies the lattice closure failure associated with a dislocation and gives the slip direction used in the lecture.","detail":"For an ideal edge dislocation b is perpendicular to the dislocation line; for an ideal screw dislocation b is parallel.","tags":["week 4","dislocation","slip"]}];
  const seen = new Set((course.reference || []).map((r) => r.id));
